-- Legacy finance schema reconstructed from the supplied 2026-10-12 metadata report.
-- Synthetic auth/storage adapters only; NEVER run this fixture on a hosted project.
CREATE SCHEMA auth;
CREATE SCHEMA storage;
CREATE TABLE auth.users(id uuid PRIMARY KEY, email text, raw_user_meta_data jsonb DEFAULT '{}');
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb) $$;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT (auth.jwt()->>'sub')::uuid $$;
CREATE TABLE storage.buckets(id text PRIMARY KEY, public boolean DEFAULT false);
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bucket_id text REFERENCES storage.buckets(id), name text);
CREATE FUNCTION storage.foldername(name text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1] $$;
GRANT USAGE ON SCHEMA public, auth, storage TO anon, authenticated;


CREATE TABLE public."Tasks" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "| Column name   | Type          | Required? | | ------------- |" timestamp with time zone DEFAULT now() NOT NULL,
  "title" text DEFAULT 'required '::text NOT NULL,
  "description" text DEFAULT 'required '::text NOT NULL,
  "reward" numeric,
  "status" text DEFAULT 'active'::text
);

CREATE TABLE public."account_balances" (
  "user_id" uuid NOT NULL,
  "balance" numeric DEFAULT 0 NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."deposits" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid NOT NULL,
  "amount" numeric NOT NULL,
  "payment_method" text NOT NULL,
  "status" text DEFAULT 'pending'::text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."internal_transfers" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "sender_id" uuid NOT NULL,
  "recipient_reference" text NOT NULL,
  "amount" numeric NOT NULL,
  "status" text DEFAULT 'pending'::text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "recipient_id" uuid
);

CREATE TABLE public."profiles" (
  "id" uuid NOT NULL,
  "invitation_code" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."referrals" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "invited_user_id" uuid NOT NULL,
  "inviter_user_id" uuid NOT NULL,
  "invitation_code" text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."task_submissions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "task_id" bigint NOT NULL,
  "proof_text" text,
  "proof_image_url" text,
  "status" text DEFAULT 'pending'::text NOT NULL,
  "submitted_at" timestamp with time zone DEFAULT now() NOT NULL,
  "reviewed_at" timestamp with time zone
);

CREATE TABLE public."withdrawals" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid NOT NULL,
  "amount" numeric NOT NULL,
  "payment_method" text NOT NULL,
  "status" text DEFAULT 'pending'::text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

