CREATE OR REPLACE FUNCTION public.approve_deposit(deposit_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  deposit_user_id uuid;
  deposit_amount numeric;
  deposit_status text;
begin

  -- Only an admin can approve deposits
  if (auth.jwt() -> 'app_metadata' ->> 'role') <> 'admin' then
    raise exception 'Only admins can approve deposits.';
  end if;

  -- Get and lock the deposit
  select
    user_id,
    amount,
    status
  into
    deposit_user_id,
    deposit_amount,
    deposit_status
  from public.deposits
  where id = deposit_id
  for update;

  if deposit_user_id is null then
    raise exception 'Deposit not found.';
  end if;

  -- Prevent duplicate credit
  if deposit_status <> 'pending' then
    raise exception 'This deposit has already been processed.';
  end if;

  -- Make sure balance account exists
  insert into public.account_balances (
    user_id,
    balance
  )
  values (
    deposit_user_id,
    0
  )
  on conflict (user_id) do nothing;

  -- Add deposit to real balance
  update public.account_balances
  set
    balance = balance + deposit_amount,
    updated_at = now()
  where user_id = deposit_user_id;

  -- Mark deposit as approved
  update public.deposits
  set
    status = 'approved'
  where id = deposit_id;

end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_task_submission(submission_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  submission_user_id uuid;
  submission_task_id bigint;
  submission_status text;
  task_reward numeric;
begin

  -- Only an admin can approve task submissions
  if (auth.jwt() -> 'app_metadata' ->> 'role') <> 'admin' then
    raise exception 'Only admins can approve task submissions.';
  end if;

  -- Lock and get the submission
  select
    user_id,
    task_id,
    status
  into
    submission_user_id,
    submission_task_id,
    submission_status
  from public.task_submissions
  where id = submission_id
  for update;

  if submission_user_id is null then
    raise exception 'Task submission not found.';
  end if;

  -- Prevent duplicate rewards
  if submission_status <> 'pending' then
    raise exception 'This task submission has already been processed.';
  end if;

  -- Get the task reward
  select reward
  into task_reward
  from public."Tasks"
  where id = submission_task_id;

  if task_reward is null then
    raise exception 'Task reward not found.';
  end if;

  -- Make sure the user's balance account exists
  insert into public.account_balances (
    user_id,
    balance
  )
  values (
    submission_user_id,
    0
  )
  on conflict (user_id) do nothing;

  -- Add the task reward
  update public.account_balances
  set
    balance = balance + task_reward,
    updated_at = now()
  where user_id = submission_user_id;

  -- Approve the submission
  update public.task_submissions
  set
    status = 'approved',
    reviewed_at = now()
  where id = submission_id;

end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_withdrawal(withdrawal_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  withdrawal_user_id uuid;
  withdrawal_amount numeric;
  withdrawal_status text;
  current_balance numeric;
begin

  -- Only an admin can approve withdrawals
  if (auth.jwt() -> 'app_metadata' ->> 'role') <> 'admin' then
    raise exception 'Only admins can approve withdrawals.';
  end if;

  -- Get the withdrawal
  select
    user_id,
    amount,
    status
  into
    withdrawal_user_id,
    withdrawal_amount,
    withdrawal_status
  from public.withdrawals
  where id = withdrawal_id
  for update;

  if withdrawal_user_id is null then
    raise exception 'Withdrawal request not found.';
  end if;

  -- Prevent approving the same withdrawal twice
  if withdrawal_status <> 'pending' then
    raise exception 'This withdrawal has already been processed.';
  end if;

  -- Get the user's real balance
  select balance
  into current_balance
  from public.account_balances
  where user_id = withdrawal_user_id
  for update;

  if current_balance is null then
    raise exception 'User balance account not found.';
  end if;

  -- Check available balance
  if current_balance < withdrawal_amount then
    raise exception 'Insufficient available balance.';
  end if;

  -- Deduct the withdrawal amount
  update public.account_balances
  set
    balance = balance - withdrawal_amount,
    updated_at = now()
  where user_id = withdrawal_user_id;

  -- Mark withdrawal as approved
  update public.withdrawals
  set
    status = 'approved'
  where id = withdrawal_id;

end;
$function$;

CREATE OR REPLACE FUNCTION public.create_internal_transfer(recipient_reference text, transfer_amount numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  sender_user_id uuid;
  recipient_user_id uuid;
  transfer_id uuid;
  sender_balance numeric;
begin

  -- Get logged-in sender
  sender_user_id := auth.uid();

  if sender_user_id is null then
    raise exception 'You must be logged in.';
  end if;

  -- Validate amount
  if transfer_amount is null or transfer_amount <= 0 then
    raise exception 'Transfer amount must be greater than zero.';
  end if;

  -- Find recipient
  recipient_user_id :=
    public.find_user_by_reference(recipient_reference);

  if recipient_user_id is null then
    raise exception 'Recipient not found.';
  end if;

  -- Prevent self-transfer
  if recipient_user_id = sender_user_id then
    raise exception 'You cannot transfer funds to yourself.';
  end if;

  -- Make sure recipient has a balance record
  insert into public.account_balances (
    user_id,
    balance
  )
  values (
    recipient_user_id,
    0
  )
  on conflict (user_id) do nothing;

  -- Lock sender balance
  select balance
  into sender_balance
  from public.account_balances
  where user_id = sender_user_id
  for update;

  if sender_balance is null then
    raise exception 'Sender balance account not found.';
  end if;

  -- Check available balance
  if sender_balance < transfer_amount then
    raise exception 'Insufficient available balance.';
  end if;

  -- Deduct from sender
  update public.account_balances
  set
    balance = balance - transfer_amount,
    updated_at = now()
  where user_id = sender_user_id;

  -- Credit recipient
  update public.account_balances
  set
    balance = balance + transfer_amount,
    updated_at = now()
  where user_id = recipient_user_id;

  -- Record completed transfer
  insert into public.internal_transfers (
    sender_id,
    recipient_id,
    recipient_reference,
    amount,
    status
  )
  values (
    sender_user_id,
    recipient_user_id,
    upper(trim(recipient_reference)),
    transfer_amount,
    'completed'
  )
  returning id into transfer_id;

  return transfer_id;

end;
$function$;

CREATE OR REPLACE FUNCTION public.generate_invitation_code()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  new_code text;
begin
  loop
    new_code := upper(substr(md5(random()::text), 1, 8));

    exit when not exists (
      select 1
      from public.profiles
      where invitation_code = new_code
    );
  end loop;

  return new_code;
end;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  INSERT INTO public.profiles (id, invitation_code)
  VALUES (NEW.id, public.generate_invitation_code());
  RETURN NEW;
END;
$function$;

-- The production reference helper was omitted by the original report's name filter.
-- This synthetic adapter follows the USER-XXXXXXXX format displayed by the website.
CREATE FUNCTION public.find_user_by_reference(ref text) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
 SELECT id FROM auth.users WHERE 'USER-' || upper(left(id::text,8)) = upper(btrim(ref))
$$;
GRANT ALL ON ALL TABLES IN SCHEMA public, storage TO anon, authenticated;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated;

-- Preserve the existing signup trigger and its restricted API permissions.
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
